#!/bin/bash
# Uninstall script for Azure CLI
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Azure CLI..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Azure CLI if running..."
pkill -f "Azure CLI" 2>/dev/null || true

# Remove /usr/local/bin/az
echo "Removing /usr/local/bin/az..."
if [ -d "/usr/local/bin/az" ]; then
    rm -rf "/usr/local/bin/az" 2>/dev/null || true
elif [ -f "/usr/local/bin/az" ]; then
    rm -f "/usr/local/bin/az" 2>/dev/null || true
fi

# Remove /usr/local/lib/intunebrew/azure_cli
echo "Removing /usr/local/lib/intunebrew/azure_cli..."
if [ -d "/usr/local/lib/intunebrew/azure_cli" ]; then
    rm -rf "/usr/local/lib/intunebrew/azure_cli" 2>/dev/null || true
elif [ -f "/usr/local/lib/intunebrew/azure_cli" ]; then
    rm -f "/usr/local/lib/intunebrew/azure_cli" 2>/dev/null || true
fi

# Remove package com.intunebrew.azure_cli
echo "Removing package com.intunebrew.azure_cli..."
pkgutil --forget com.intunebrew.azure_cli 2>/dev/null || true

echo "Uninstallation complete!"
exit 0
